1	import type {ChatSession} from '../types/session.js';
2	import type {ToolRegistry, ToolContext, ToolResponse} from './tools/registry.js';
3	import type {
4	  AIProvider,
5	  AggregatedUsage,
6	  Message,
7	  MessageChunk,
8	  SendMessageParams,
9	  ToolCall,
10	  ToolResultContent,
11	  UsageMetadata,
12	} from '../types/ai.js';
13	import type {OutgoingMessage} from '../types/messages.js';
14	import type {PromptBuilder, PromptBuilderOptions} from '../infrastructure/builders/promptBuilder.js';
15	import type {SessionStore} from '../types/sessionStore.js';
16	import {toMessages, createContextConfig} from './conversationContext.js';
17	import type {ContextConfig} from './conversationContext.js';
18	import {
19	  shouldContinueToolLoop,
20	  collectText,
21	  buildToolCallMessages,
22	  collectToolCalls,
23	  extractStopReason,
24	  extractUsage,
25	  sumUsage,
26	} from './orchestratorHelpers.js';
27	import {appendEntry, commitStreamingEntries} from './entryMutations.js';
28	import {log} from '../shared/logger.js';
29	
30	const DEFAULT_MAX_TOOL_ROUNDS = 5;
31	
32	export interface OrchestratorHooks {
33	  beforeSession?: (session: ChatSession) => Promise<void>;
34	  afterSession?: (session: ChatSession) => Promise<void>;
35	  beforeUserInput?: (session: ChatSession, userMessage: string) => Promise<string>;
36	  afterUserInput?: (session: ChatSession, userMessage: string) => Promise<void>;
37	  beforeModelResponse?: (session: ChatSession, systemPrompt: string) => Promise<string>;
38	  afterModelResponse?: (
39	    session: ChatSession,
40	    responseText: string,
41	    usage?: AggregatedUsage,
42	    rounds?: UsageMetadata[]
43	  ) => Promise<void>;
44	  onError?: (session: ChatSession, error: Error) => Promise<void>;
45	  /** The supported seam for an EU AI Act Art. 14 human-oversight control: fires before each known tool's executor, and a returned ToolResponse replaces the call (see docs/adding-a-tool.md); it receives the model's raw tool input and, through session, the caller's authHeaders, so a policy that logs either logs personal data and credential material; the engine asserts nothing about any policy installed here. */
46	  beforeToolCall?: (session: ChatSession, call: ToolCall) => Promise<ToolResponse | undefined>;
47	  /** Fires when the model asks for a tool round the budget refuses, after the last provider call and before afterModelResponse; a returned string reaches the user as the turn's closing text, and the engine writes none of its own (see specs/hal-engine-tool-budget/spec.md). */
48	  onToolBudgetExhausted?: (session: ChatSession, budget: ToolBudgetInfo) => Promise<string | undefined>;
49	}
50	
51	export interface ToolBudgetInfo {
52	  maxToolRounds: number;
53	  requestedTools: string[];
54	}
55	
56	type BeforeToolCall = NonNullable<OrchestratorHooks['beforeToolCall']>;
57	type OnToolBudgetExhausted = NonNullable<OrchestratorHooks['onToolBudgetExhausted']>;
58	
59	export const TOOL_BUDGET_EXHAUSTED = 'tool_budget_exhausted';
60	
61	export interface ChatOrchestrator {
62	  processMessage(session: ChatSession): Promise<string>;
63	  processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk>;
64	}
65	
66	export interface ChatOrchestratorOptions {
67	  maxToolRounds?: number;
68	  contextConfig?: Partial<ContextConfig>;
69	  promptBuilderOptions?: PromptBuilderOptions;
70	  hooks?: OrchestratorHooks;
71	  sessionStore?: SessionStore;
72	}
73	
74	interface ToolExecutionResult {
75	  clientMessages: OutgoingMessage[];
76	  suppressOutput: boolean;
77	}
78	export function createChatOrchestrator(
79	  provider: AIProvider,
80	  promptBuilder: PromptBuilder,
81	  toolRegistry?: ToolRegistry,
82	  options?: ChatOrchestratorOptions
83	): ChatOrchestrator {
84	  const maxToolRounds = normalizeToolRounds(options?.maxToolRounds);
85	  const contextConfig = createContextConfig(options?.contextConfig);
86	  const toolInstructions = toolRegistry?.getPromptInstructions();
87	  const baseSystemPrompt = promptBuilder.build({...options?.promptBuilderOptions, toolInstructions});
88	  const tools = toolRegistry?.getDefinitions();
89	  const hooks = options?.hooks;
90	  const sessionStore = options?.sessionStore;
91	
92	  return {
93	    async processMessage(session: ChatSession): Promise<string> {
94	      return collectText(this.processMessageStream(session));
95	    },
96	
97	    async *processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk> {
98	      try {
99	        if (hooks?.beforeSession) await hooks.beforeSession(session);
100	
101	        let userMessage = lastUserContent(session);
102	
103	        if (hooks?.beforeUserInput) {
104	          userMessage = await rewriteUserMessage(session, userMessage, hooks.beforeUserInput);
105	        }
106	
107	        if (hooks?.afterUserInput) await hooks.afterUserInput(session, userMessage);
108	
109	        const systemPrompt = hooks?.beforeModelResponse
110	          ? await hooks.beforeModelResponse(session, baseSystemPrompt)
111	          : baseSystemPrompt;
112	
113	        const messages: Message[] = toMessages(session.entries, contextConfig);
114	        const usageRounds: UsageMetadata[] = [];
115	        let responseText = '';
116	
117	        // Bounded by the budget gate below, not the header: maxToolRounds executed rounds, maxToolRounds + 1 provider calls.
118	        for (let round = 0; ; round++) {
119	          log.info('orchestrator', 'starting round', {round});
120	          const pendingToolCalls: ToolCall[] = [];
121	
122	          const outcome = yield* streamRound(provider, {messages, systemPrompt, tools}, pendingToolCalls);
123	          responseText += outcome.text;
124	          if (outcome.usage !== undefined) usageRounds.push(outcome.usage);
125	
126	          if (!shouldContinueToolLoop(outcome.stopReason, pendingToolCalls, toolRegistry)) break;
127	          if (budgetSpent(round, maxToolRounds, pendingToolCalls)) {
128	            const budget = {maxToolRounds, requestedTools: pendingToolCalls.map(tc => tc.name)};
129	            responseText += yield* closeExhaustedTurn(session, budget, hooks?.onToolBudgetExhausted);
130	            break;
131	          }
132	
133	          log.info('orchestrator', 'executing tools', {tools: pendingToolCalls.map(tc => tc.name)});
134	          const {clientMessages, suppressOutput} = await executeToolCalls(
135	            pendingToolCalls,
136	            messages,
137	            session,
138	            toolCallRunner(toolRegistry!, session, hooks?.beforeToolCall)
139	          );
140	          log.info('orchestrator', 'tool execution complete', {
141	            clientMessageCount: clientMessages.length,
142	            clientMessageTypes: clientMessages.map(m => m.type),
143	            suppressOutput,
144	          });
145	
146	          if (clientMessages.length > 0) {
147	            yield {type: 'tool_result' as const, clientMessages};
148	          }
149	
150	          if (suppressOutput) {
151	            yield {type: 'suppress_output' as const};
152	          }
153	        }
154	
155	        if (hooks?.afterModelResponse)
156	          await hooks.afterModelResponse(session, responseText, sumUsage(usageRounds), usageRounds);
157	      } catch (error) {
158	        if (hooks?.onError && error instanceof Error) {
159	          await hooks.onError(session, error);
160	        }
161	        throw error;
162	      } finally {
163	        // Before both: a provider that threw mid-stream leaves an entry open, and nothing should persist it that way.
164	        commitStreamingEntries(session);
165	        try {
166	          if (hooks?.afterSession) await hooks.afterSession(session);
167	        } finally {
168	          await saveSession(sessionStore, session);
169	        }
170	      }
171	    },
172	  };
173	}
174	
175	// A negative budget means no tool rounds; a non-finite one, NaN included, falls back to the default rather than never ending.
176	function normalizeToolRounds(value: number | undefined): number {
177	  if (value === undefined || !Number.isFinite(value)) return DEFAULT_MAX_TOOL_ROUNDS;
178	  return Math.max(0, Math.floor(value));
179	}
180	
181	// Gates execution, not the provider call: a round nobody can read is never run, and the call that read the last one already has.
182	function budgetSpent(round: number, maxToolRounds: number, pendingToolCalls: ToolCall[]): boolean {
183	  if (round < maxToolRounds) return false;
184	  log.warn('orchestrator', 'tool budget exhausted', {
185	    maxToolRounds,
186	    requestedTools: pendingToolCalls.map(tc => tc.name),
187	  });
188	  return true;
189	}
190	
191	// The stop always follows the text: the round's own stop already committed its entry, and a bare text chunk would open one never committed.
192	async function* closeExhaustedTurn(
193	  session: ChatSession,
194	  budget: ToolBudgetInfo,
195	  hook?: OnToolBudgetExhausted
196	): AsyncGenerator<MessageChunk, string> {
197	  const sentence = (hook ? await hook(session, budget) : undefined) ?? '';
198	  if (sentence !== '') yield {type: 'text', text: sentence};
199	  yield {type: 'stop', stopReason: TOOL_BUDGET_EXHAUSTED};
200	  return sentence;
201	}
202	
203	interface RoundOutcome {
204	  stopReason: string;
205	  text: string;
206	  usage?: UsageMetadata;
207	}
208	
209	// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
210	async function* streamRound(
211	  provider: AIProvider,
212	  request: SendMessageParams,
213	  pendingToolCalls: ToolCall[]
214	): AsyncGenerator<MessageChunk, RoundOutcome> {
215	  let stopReason = '';
216	  let text = '';
217	  let usage: UsageMetadata | undefined;
218	
219	  for await (const chunk of provider.sendMessage(request)) {
220	    yield chunk;
221	    collectToolCalls(chunk, pendingToolCalls);
222	    stopReason = extractStopReason(chunk) ?? stopReason;
223	    usage = extractUsage(chunk) ?? usage;
224	    if (chunk.type === 'text') text += chunk.text;
225	  }
226	
227	  return {stopReason, text, usage};
228	}
229	
230	// A changed message is also written back to the session's last user entry.
231	async function rewriteUserMessage(
232	  session: ChatSession,
233	  userMessage: string,
234	  hook: (session: ChatSession, userMessage: string) => Promise<string>
235	): Promise<string> {
236	  const modified = await hook(session, userMessage);
237	  if (modified === userMessage) return userMessage;
238	
239	  updateLastUserContent(session, modified);
240	  return modified;
241	}
242	
243	function lastUserContent(session: ChatSession): string {
244	  for (let i = session.entries.length - 1; i >= 0; i--) {
245	    const entry = session.entries[i];
246	    if (entry.role === 'user') return entry.content;
247	  }
248	  return '';
249	}
250	
251	function updateLastUserContent(session: ChatSession, content: string): void {
252	  for (let i = session.entries.length - 1; i >= 0; i--) {
253	    const entry = session.entries[i];
254	    if (entry.role === 'user') {
255	      entry.content = content;
256	      return;
257	    }
258	  }
259	}
260	
261	// One runner per round: the policy sees each known call before its executor, and an unknown name keeps the registry's own path.
262	function toolCallRunner(toolRegistry: ToolRegistry, session: ChatSession, beforeToolCall?: BeforeToolCall) {
263	  const context: ToolContext = {
264	    userId: session.userId,
265	    sessionId: session.sessionId,
266	    workspaceId: session.workspaceId,
267	    authHeaders: session.authHeaders,
268	  };
269	
270	  return async (tc: ToolCall): Promise<ToolResponse> => {
271	    const declined =
272	      beforeToolCall && toolRegistry.has(tc.name) ? await consultPolicy(beforeToolCall, session, tc) : undefined;
273	    return declined ?? toolRegistry.execute(tc.name, tc.input, context);
274	  };
275	}
276	
277	// A throwing policy declines its call rather than failing the turn: every tool_use must still be answered.
278	async function consultPolicy(
279	  policy: BeforeToolCall,
280	  session: ChatSession,
281	  tc: ToolCall
282	): Promise<ToolResponse | undefined> {
283	  try {
284	    return await policy(session, tc);
285	  } catch (error) {
286	    log.warn('orchestrator', 'beforeToolCall threw, so the call is declined', {
287	      tool: tc.name,
288	      errorType: error instanceof Error ? error.name : typeof error,
289	    });
290	    return {result: `The ${tc.name} call was declined and not performed.`};
291	  }
292	}
293	
294	async function executeToolCalls(
295	  pendingToolCalls: ToolCall[],
296	  messages: Message[],
297	  session: ChatSession,
298	  runToolCall: (tc: ToolCall) => Promise<ToolResponse>
299	): Promise<ToolExecutionResult> {
300	  messages.push(buildToolCallMessages(pendingToolCalls));
301	
302	  const responses = await Promise.all(
303	    pendingToolCalls.map(async tc => {
304	      const response = await runToolCall(tc);
305	      return {tc, response};
306	    })
307	  );
308	
309	  const toolResults: ToolResultContent[] = responses.map(({tc, response}) => ({
310	    type: 'tool_result' as const,
311	    toolUseId: tc.id,
312	    content: response.result,
313	  }));
314	  messages.push({role: 'user', content: toolResults});
315	
316	  const rawClientMessages = responses.flatMap(({response}) => response.clientMessages ?? []);
317	
318	  return {
319	    clientMessages: assignEntryIndices(rawClientMessages, session),
320	    suppressOutput: responses.some(({response}) => response.suppressAssistantResponse === true),
321	  };
322	}
323	
324	function assignEntryIndices(clientMessages: OutgoingMessage[], session: ChatSession): OutgoingMessage[] {
325	  return clientMessages.map(msg => {
326	    if (msg.type !== 'entry_upsert') return msg;
327	    const index = appendEntry(session, msg.entry);
328	    return {...msg, index};
329	  });
330	}
331	
332	// A store outage is not a reason to fail the turn the customer already received.
333	async function saveSession(store: SessionStore | undefined, session: ChatSession): Promise<void> {
334	  if (!store?.save) return;
335	
336	  try {
337	    await store.save(session);
338	  } catch (error) {
339	    const message = error instanceof Error ? error.message : String(error);
340	    log.error('orchestrator', 'session save failed', {sessionId: session.sessionId, error: message});
341	  }
342	}
